// Thistlevane — HUD icon sheet (16×16 cells, drawn 1:1, shown at 2× in the hotbar)
// Order matters: the hotbar addresses icons by column index.
//   0 strike · 1 thistle bolt · 2 guard · 3 dash · 4 salve · 5 lantern
// Build:  node .claude/skills/pxl-pixel-art/bin/pxl.js build assets/prototype/ui-icons.px.js
// Output: out/ui_icons.png -> assets/ui/icons.png

pal({
  K: "#1a1020",                                   // outline (art bible: Deep Bark)
  m: "#e8ecf8", M: "#98a0b8", x: "#5a6076",       // steel
  q: "#8a5a30", Q: "#5a3a1c",                     // wood / leather
  o: "#f0c860", O: "#a07820",                     // gold
  g: "#9ad860", G: "#5a9830", d: "#2e6020",       // leaf green
  v: "#c898d8", V: "#8058a0",                     // thistle bloom
  r: "#f06858", R: "#a83040",                     // salve red
  s: "#f4e8c8", S: "#c8b080",                     // cloth / glass highlight
  t: "#78d8c0", T: "#38907c",                     // guard sheen
  y: "#ffe9a8", Y: "#d8a030",                     // lantern flame
})

// 0 — STRIKE: the short sword, angled like the attack pose.
sprite("icon_strike", { w: 16, h: 16, outline: "K" }, `
................
.............m..
............mM..
...........mM...
..........mM....
.........mM.....
........mM......
.......mM.......
......mM........
.o...mM.........
..oOmM..........
...oOo..........
..qoQ...........
.qq.............
Q...............
................`)

// 1 — THISTLE BOLT: the hedge-mage's nature spell.
sprite("icon_bolt", { w: 16, h: 16, outline: "K" }, `
.......v........
......vVv.......
.....vvVvv......
....vvVVVvv.....
.....vvVvv......
......gGg.......
.....gGGGg......
......gGg.......
.......G........
....g..G..g.....
...gG..G..Gg....
....gG.G.Gg.....
.....gGGGg......
.......G........
.......d........
................`)

// 2 — GUARD: a round shield with a boss and a bound rim.
sprite("icon_guard", { w: 16, h: 16, outline: "K" }, `
....QQQQQQ......
...QttttttQ.....
..QttttttttQ....
..QtttTTtttQ....
.QttTTTTTTttQ...
.QttTToottTtQ...
.QtTTooooTTtQ...
.QtTTooooTTtQ...
.QttTToottTtQ...
.QttTTTTTTttQ...
..QtttTTtttQ....
..QttttttttQ....
...QttttttQ.....
....QttttQ......
.....QQQQ.......
................`)

// 3 — DASH: a travelling boot with speed lines.
sprite("icon_dash", { w: 16, h: 16, outline: "K" }, `
................
................
.....qqqq.......
....qssssq......
....qQQQQq......
.s..qQQQQq......
ss..qQQQQq......
.s..qQQQQq......
s...qQQQQqq.....
ss..qQQQQQQqq...
.s..qQQQQQQQQq..
....qQQQQQQQQq..
....xxxxxxxxxx..
................
................
................
`)

// 4 — SALVE: a stoppered flask of red tonic.
sprite("icon_salve", { w: 16, h: 16, outline: "K" }, `
......QQ........
......QQ........
.....sSSs.......
.....S..S.......
....Ss..sS......
....S....S......
...Ss....sS.....
...S.rrrr.S.....
...SsrrrrrS.....
...SsrrrrrS.....
...SrRRRRrS.....
...SrRRRRrS.....
....SRRRRS......
....sSRRSs......
.....SSSS.......
................
`)

// 5 — LANTERN: the scholar's light, the game's own motif.
sprite("icon_lantern", { w: 16, h: 16, outline: "K" }, `
.......O........
......oOo.......
.......O........
.....ooooo......
....oyyyyyo.....
....oyYYYyo.....
....oyYsYyo.....
....oyYsYyo.....
....oyYYYyo.....
....oyyyyyo.....
.....ooooo......
......ooo.......
................
................
................
................
`)

// `outline` grows each sprite to 18×18; the sheet is composed by hand so the
// cells stay exactly 16×16 and the hotbar can address them with whole numbers.
const ICONS = ["icon_strike", "icon_bolt", "icon_guard", "icon_dash", "icon_salve", "icon_lantern"]
scene("ui_icons", { w: 16 * ICONS.length, h: 16 },
  ...ICONS.map((id, i) => stamp(id, i * 16 - 1, -1)))
